func TestImport_Namespaces(t *testing.T) {
	tests := []struct {
		name         string
		docNamespace string
		cliNamespace string
		wantError    bool
	}{
		{
			name:         "import with namespace",
			docNamespace: "namespace1",
			cliNamespace: "namespace1",
